def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the non-uniform, contiguous color key line.
    candidates = []
    for r in range(h):
        vals = [grid[r][c] for c in range(w)]
        nz = [c for c,v in enumerate(vals) if v]
        if len(nz) >= 2 and nz == list(range(nz[0], nz[-1]+1)) and len(set(vals[nz[0]:nz[-1]+1])) > 1:
            candidates.append((len(nz), vals[nz[0]:nz[-1]+1], 'row'))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        nz = [r for r,v in enumerate(vals) if v]
        if len(nz) >= 2 and nz == list(range(nz[0], nz[-1]+1)) and len(set(vals[nz[0]:nz[-1]+1])) > 1:
            candidates.append((len(nz), vals[nz[0]:nz[-1]+1], 'col'))
    _, palette, _ = min(candidates, key=lambda item: item[0])
    # The color-1 drawing is the template; place one copy for each key color.
    ones = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    components = []
    while ones:
        seed = ones.pop()
        comp, stack = {seed}, [seed]
        while stack:
            r,c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in ones:
                    ones.remove(q); comp.add(q); stack.append(q)
        components.append(comp)
    pts = max(components, key=len)
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    mask = [(r-r0,c-c0) for r,c in pts]
    idx = palette.index(1)
    out = [[0]*w for _ in range(h)]
    for i, color in enumerate(palette):
        top = r0 + (i-idx)*(r1-r0+1)
        for dr,dc in mask:
            rr,cc = top+dr,c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out

